class FDCPRadioTable {
    constructor(element) {
        this.element = element;
        this.optionHeadings = this.element.querySelectorAll(
            '.fdcp-radio-table__option-heading'
        );

        if (this.optionHeadings.length > 0) {
            this.element.style.setProperty(
                '--fdcp-radio-option-count',
                this.optionHeadings.length
            );
        }

        this.requiredRows = Array.from(
            this.element.querySelectorAll('.fdcp-radio--required')
        );
        this.bindValidation();

        this.breakpoint = 48 * Number.parseFloat(
            getComputedStyle(document.documentElement).fontSize
        );
        this.resizeObserver = new ResizeObserver(entries => {
            entries.forEach(entry => this.updateLayout(entry.contentRect.width));
        });

        this.updateLayout(this.element.getBoundingClientRect().width);
        this.resizeObserver.observe(this.element);

        if (document.fonts) {
            document.fonts.ready.then(() => {
                this.updateLayout(this.element.getBoundingClientRect().width);
            });
        }
    }

    bindValidation() {
        this.requiredRows.forEach(row => {
            const inputs = Array.from(
                row.querySelectorAll('.fdcp-radio__input[type="radio"]')
            );

            inputs.forEach((input, index) => {
                input.required = true;

                input.addEventListener('change', () => {
                    if (row.classList.contains('fdcp-radio--error')) {
                        this.validateRow(row);
                    }
                });

                input.addEventListener('invalid', event => {
                    event.preventDefault();

                    if (index === 0) {
                        this.validateRow(row, { focus: true });
                    }
                });
            });

            row.addEventListener('focusout', event => {
                if (!row.contains(event.relatedTarget)) {
                    this.validateRow(row);
                }
            });
        });

        const form = this.element.closest('form');
        form?.addEventListener('submit', event => {
            const isValid = this.requiredRows
                .map(row => this.validateRow(row))
                .every(Boolean);

            if (!isValid) {
                event.preventDefault();
                this.requiredRows
                    .find(row => !this.isRowValid(row))
                    ?.querySelector('.fdcp-radio__input')
                    ?.focus();
            }
        });
    }

    isRowValid(row) {
        const enabledInputs = Array.from(
            row.querySelectorAll('.fdcp-radio__input[type="radio"]:not(:disabled)')
        );

        return enabledInputs.length === 0 || enabledInputs.some(input => input.checked);
    }

    validateRow(row, { focus = false } = {}) {
        const inputs = Array.from(
            row.querySelectorAll('.fdcp-radio__input[type="radio"]')
        );
        const firstInput = inputs.find(input => !input.disabled);
        const error = row.querySelector('[data-fdcp-radio-error]');
        const isValid = this.isRowValid(row);

        row.classList.toggle('fdcp-radio--error', !isValid);

        inputs.forEach(input => {
            if (isValid) {
                input.removeAttribute('aria-invalid');
                input.removeAttribute('aria-describedby');
            } else {
                input.setAttribute('aria-invalid', 'true');

                if (error?.id) {
                    input.setAttribute('aria-describedby', error.id);
                }
            }
        });

        if (error) {
            error.hidden = isValid;
        }

        if (!firstInput) {
            return true;
        }

        if (isValid) {
            firstInput.dispatchEvent(new CustomEvent('gcdsValid', {
                bubbles: true,
                composed: true
            }));
        } else {
            firstInput.dispatchEvent(new CustomEvent('gcdsError', {
                bubbles: true,
                composed: true,
                detail: {
                    message: row.dataset.requiredSummaryMessage
                        || row.dataset.requiredMessage
                        || 'This field is required.'
                }
            }));

            if (focus) {
                firstInput.focus();
            }
        }

        return isValid;
    }

    updateLayout(width) {
        if (width < this.breakpoint) {
            this.element.classList.remove('fdcp-radio-table--wide');
            return;
        }

        this.element.classList.add('fdcp-radio-table--wide');

        const hasOverflowingHeading = Array.from(this.optionHeadings).some(heading => {
            const range = document.createRange();
            range.selectNodeContents(heading);

            const lineTops = Array.from(range.getClientRects())
                .filter(rect => rect.width > 0 && rect.height > 0)
                .reduce((tops, rect) => {
                    if (!tops.some(top => Math.abs(top - rect.top) < 1)) {
                        tops.push(rect.top);
                    }

                    return tops;
                }, []);

            return lineTops.length > 3;
        });

        if (hasOverflowingHeading) {
            this.element.classList.remove('fdcp-radio-table--wide');
        }
    }
}

document.addEventListener('DOMContentLoaded', () => {
    document.querySelectorAll('[data-fdcp-radio-table]').forEach(element => {
        new FDCPRadioTable(element);
    });
});
